请对以下 case 进行三维加权评分。

=== case_id ===
Case-07-sports-event-012

=== 用户原始指令 (query.txt) ===
下周要跑半马了，帮我做一个赛事倒计时卡片，要左右分区那种。左边信息区显示"距离比赛还有7天"这种固定文字+动态天数的拼接，下面再分几个小格子放赛前准备清单，像"装备已就绪""能量胶已购""配速已测试"，打勾的就是正向完成态。右边动作区放个"查看日程"按钮，点进去能看具体的赛事日程事件，帮我读日历日程里的内容。卡片底色分区来，左边偏深紫右边偏深蓝，整体用夜晚跑步的氛围渐变。下面还要纵向排列多项检查项，每项前面用语义图标，像跑鞋、水壶、奖牌那种。

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "下周要跑半马了，帮我做一个赛事倒计时卡片，要左右分区那种。左边信息区显示\"距离比赛还有7天\"这种固定文字+动态天数的拼接，下面再分几个小格子放赛前准备清单，像\"装备已就绪\"\"能量胶已购\"\"配速已测试\"，打勾的就是正向完成态。右边动作区放个\"查看日程\"按钮，点进去能看具体的赛事日程事件，帮我读日历日程里的内容。卡片底色分区来，左边偏深紫右边偏深蓝，整体用夜晚跑步的氛围渐变。下面还要纵向排列多项检查项，每项前面用语义图标，像跑鞋、水壶、奖牌那种。",
  "size": "2x4",
  "eventCandidates": [
    {
      "call": "clickToIntent",
      "args": {
        "intentName": "ViewCalendarEvent",
        "params": {
          "entityId": "event-half-marathon-001"
        }
      }
    }
  ],
  "dataModelSchema": {
    "race": {
      "daysUntilRace": {
        "type": "number",
        "description": "距离半马比赛开始的剩余天数，用于倒计时拼接展示。",
        "sampleValue": 7
      },
      "prep": {
        "gear": {
          "label": {
            "type": "string",
            "description": "赛前装备准备状态短文案。",
            "sampleValue": "装备已就绪"
          },
          "done": {
            "type": "boolean",
            "description": "装备准备是否已完成，选中表示正向完成态。",
            "sampleValue": true
          }
        },
        "gel": {
          "label": {
            "type": "string",
            "description": "能量补给准备状态短文案。",
            "sampleValue": "能量胶已购"
          },
          "done": {
            "type": "boolean",
            "description": "能量补给是否已完成，选中表示正向完成态。",
            "sampleValue": true
          }
        },
        "pace": {
          "label": {
            "type": "string",
            "description": "配速测试准备状态短文案。",
            "sampleValue": "配速已测试"
          },
          "done": {
            "type": "boolean",
            "description": "配速测试是否已完成，选中表示正向完成态。",
            "sampleValue": true
          }
        }
      }
    },
    "data": {
      "calendar": {
        "items": [
          {
            "entityId": {
              "type": "string",
              "description": "日历日程详情页所需的事件唯一标识。",
              "sampleValue": "event-half-marathon-001"
            },
            "title": {
              "type": "string",
              "description": "半马比赛相关日程标题。",
              "sampleValue": "半马比赛日程"
            },
            "dtStart": {
              "type": "string",
              "description": "赛事日程起始时间，若为当天日程则使用 HH:MM 格式。",
              "sampleValue": "07:30"
            },
            "dtEnd": {
              "type": "string",
              "description": "赛事日程结束时间，若为当天日程则使用 HH:MM 格式。",
              "sampleValue": "11:00"
            }
          }
        ]
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/icon_run.png",
      "description": "运动跑步图标，适合表达半马、跑步赛事和装备准备。"
    },
    {
      "src": "resources/base/media/drop_1.svg",
      "description": "水滴线性图标，适合表达补水、能量补给或赛前饮水准备。"
    },
    {
      "src": "resources/base/media/stopwatch_fill.svg",
      "description": "秒表图标，适合表达运动计时、配速测试和赛事倒计时。"
    },
    {
      "src": "resources/base/media/calendar_fill.svg",
      "description": "日历图标，适合表达日程查看、赛事安排和日历事件入口。"
    }
  ]
}

